floor_fn:
"""
    Gets the first element of the iterable.

    :param iterable:
        A non-empty iterable. If it is empty a StopIteration error will be raised
    :type x:
        iterable **(A)**

    :returns:
        A
    """
def head(iterable: Any) -> object {
    it = iter(iterable);
    return next(it);
}

